{"command": "cd /tmp && cat > rt2.cpp <<'EOF'
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
int main(){
  FILE*f=fopen("/tmp/quotes.txt","r");
  std::vector<long> ts; std::vector<std::string> qs;
  char line[4096];
  while(fgets(line,sizeof line,f)){
    char*p=line; long t=strtol(p,&p,10); if(*p!='|')continue; p++;
    std::string q(p); if(!q.empty()&&q.back()=='\n')q.pop_back();
    if(q=="DONE")break;
    if(!ts.empty()&&ts.back()==t)continue;
    ts.push_back(t); qs.push_back(q);
  }
  int n=ts.size();
  std::vector<long> a(n),b(n),c(n),d(n);
  for(int i=0;i<n;i++){
    srand((unsigned)ts[i]); a[i]=rand();
    std::mt19937 g1((unsigned)ts[i]); b[i]=(long)g1();
    std::mt19937_64 g2((unsigned long long)ts[i]); c[i]=(long)(g2()%1000000007LL);
    // std::minstd_rand
    std::minstd_rand g3((unsigned)ts[i]); d[i]=(long)g3();
  }
  auto test=[&](const char*nm,const std::vector<long>&v){
    for(long N=800;N<=1300;N++){
      int bad=0,pairs=0;
      for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){
        if(v[i]%N==v[j]%N){pairs++; if(qs[i]!=qs[j])bad++;}
      }
      if(bad==0&&pairs>20) printf("%s N=%ld pairs=%d\n",nm,N,pairs);
    }
  };
  test("libc",a); test("mt19937",b); test("mt19937_64m",c); test("minstd",d);
  printf("done n=%d\n",n);
}
EOF
g++ -O2 -o rt2 rt2.cpp && ./rt2"}

