// Reimplementation of the GROMACS "gmx" command line driver.
//
// The behaviour reproduced here was established by running the reference
// executable and observing its command-line interface (banner, help texts,
// option parsing and error messages), which is the intended way to learn what
// the program does.  The help texts and option tables live in
// src/gmxdata.cpp (generated by tools/gen_data.py from data/).
#pragma once

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <cstdarg>
#include <string>
#include <vector>
#include <map>
#include "gmxdata.h"

namespace gmx {

// ---------------------------------------------------------------------------
// runtime description
// ---------------------------------------------------------------------------
struct Runtime {
    std::string exePath;     // shown after "Executable:"
    std::string progName;    // basename of argv[0]
    std::string workingDir;
    std::string commandLine; // "prog arg1 arg2 ..."
    std::string label;       // "gmx rms" for a command, progName otherwise
    bool        quiet = false;
    bool        debug = false;
    bool        backup = true;
};
extern Runtime rt;

// ---------------------------------------------------------------------------
// small helpers
// ---------------------------------------------------------------------------
std::string format(const char* fmt, ...);
std::string basename(const std::string& p);
std::string tolower(const std::string& s);
bool        fileExists(const std::string& p);
bool        isRegularFile(const std::string& p);
std::string fileExtension(const std::string& p);

// Number conversions with the exact GROMACS error strings.
// Returns "" on success, otherwise the error text (without "Invalid value: ").
std::string convertInt(const std::string& s, int* out);
std::string convertReal(const std::string& s, double* out);

// Word wrap used for error messages (width 78, keeps leading indent).
std::string wrapText(const std::string& text, int width = 78);

// ---------------------------------------------------------------------------
// error reporting
// ---------------------------------------------------------------------------
struct Source {
    const char* file;
    int         line;
    const char* func;
};
// well known throw sites of the reference implementation
extern const Source SRC_CMDLINE_PARSE;   // cmdlineparser.cpp (line 271)
extern const Source SRC_CMDLINE_POSITIONAL;
extern const Source SRC_MODULEMANAGER;   // cmdlinemodulemanager.cpp (line 389)
extern const Source SRC_OPTIONS_FINISH;  // options.cpp (line 184)
extern const Source SRC_DATAFILEFINDER;
extern const Source SRC_GROIO;
extern const Source SRC_FUTIL_OPEN;
extern const Source SRC_FFLIB;

// An error message is reported as a block on stderr and terminates the program
// with exit status 1.
[[noreturn]] void reportError(const Source& s, const std::string& kind,
                              const std::string& message);

// option validation errors are accumulated and reported together
struct OptError {
    std::string optionName; // empty for errors that belong to no option
    std::string message;    // already indented raw text
};
class ErrorSink {
  public:
    std::vector<OptError> entries;
    void add(const std::string& optionName, const std::string& msg);
    void addNoOpt(const std::string& msg);
    bool empty() const { return entries.empty(); }
    std::string text() const;
};
[[noreturn]] void throwOptErrors(const ErrorSink& e, const Source& s);

// ---------------------------------------------------------------------------
// startup / shutdown output
// ---------------------------------------------------------------------------
void printStartHeader();
void printQuote();
void printCopyright();
void printVersionInfo();
void printHelpText(const std::string& text);

// ---------------------------------------------------------------------------
// option parsing
// ---------------------------------------------------------------------------
struct OptValues {
    std::map<std::string, std::vector<std::string>> raw;   // by option name
    std::vector<std::string>                         positional;
    std::vector<std::string>                         order; // options in order seen
    bool given(const std::string& n) const { return raw.count(n) > 0; }
    std::string str(const std::string& n, const std::string& dflt) const;
    double real(const std::string& n, double dflt) const;
    long   integer(const std::string& n, long dflt) const;
};

// Parsed values for the global options.
struct GlobalOpts {
    bool help = false;
    bool quiet = false;
    bool version = false;
    bool copyright = false;
    bool backup = true;
    bool debug = false;
    long nice = 19;
    bool niceGiven = false;
};

// Parse the global options that precede the command name.  Returns the index of
// the first argument that is the command (== argv->size() when there is none).
// A fatal error is reported for parsing problems, unless help/version/copyright
// was requested, in which case it returns -1 after having printed the request.
int parseGlobalOptions(std::vector<std::string> args, GlobalOpts* go,
                       std::vector<std::string>* rest);

// Parse the options of a single command module.
OptValues parseCommandOptions(const GmxModule* mod, const std::vector<std::string>& args);

// Validate the file options and required options of a command.
void validateOptions(const GmxModule* mod, const OptValues& v);

// ---------------------------------------------------------------------------
// modules
// ---------------------------------------------------------------------------
const GmxModule* findModule(const char* name);
int runCommand(const GmxModule* mod, const OptValues& v);

} // namespace gmx
EOF
echo ok"}

