#include "gmx.h"
#include <sys/stat.h>
#include <unistd.h>
#include <cerrno>

namespace gmx {

Runtime rt;

std::string format(const char* fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    va_list ap2;
    va_copy(ap2, ap);
    int n = vsnprintf(nullptr, 0, fmt, ap);
    va_end(ap);
    std::string s;
    if (n > 0) {
        s.resize(size_t(n) + 1);
        vsnprintf(&s[0], s.size(), fmt, ap2);
        s.resize(size_t(n));
    }
    va_end(ap2);
    return s;
}

std::string basename(const std::string& p)
{
    size_t i = p.find_last_of('/');
    return i == std::string::npos ? p : p.substr(i + 1);
}

std::string tolower(const std::string& s)
{
    std::string r = s;
    for (auto& c : r) {
        c = char(tolower((unsigned char)c));
    }
    return r;
}

std::string fileExtension(const std::string& p)
{
    size_t i = p.find_last_of('.');
    if (i == std::string::npos || i == 0) {
        return "";
    }
    // A trailing slash means there is no extension
    if (p.find('/', i) != std::string::npos) {
        return "";
    }
    return p.substr(i + 1);
}

bool fileExists(const std::string& p)
{
    struct stat st;
    return ::stat(p.c_str(), &st) == 0;
}

bool isRegularFile(const std::string& p)
{
    struct stat st;
    if (::stat(p.c_str(), &st) != 0) {
        return false;
    }
    return S_ISREG(st.st_mode);
}

// ---------------------------------------------------------------------------
// number conversions
// ---------------------------------------------------------------------------
std::string convertInt(const std::string& s, int* out)
{
    const char* p = s.c_str();
    char*       end = nullptr;
    errno = 0;
    long long v = strtoll(p, &end, 10);
    if (end == p) {
        return "expected an integer";
    }
    while (*end == ' ' || *end == '\t') {
        end++;
    }
    if (*end != '\0') {
        return "expected an integer";
    }
    if (v < -2147483648LL || v > 2147483647LL) {
        return "it causes an integer overflow";
    }
    *out = int(v);
    return "";
}

std::string convertReal(const std::string& s, double* out)
{
    const char* p = s.c_str();
    char*       end = nullptr;
    errno = 0;
    double v = strtod(p, &end);
    if (end == p) {
        return "expected a number";
    }
    while (*end == ' ' || *end == '\t') {
        end++;
    }
    if (*end != '\0') {
        return "expected a number";
    }
    if (std::isinf(v)) {
        return "it causes an overflow/underflow";
    }
    *out = v;
    return "";
}

// ---------------------------------------------------------------------------
// word wrap
// ---------------------------------------------------------------------------
std::string wrapText(const std::string& text, int width)
{
    std::string out;
    size_t      i = 0;
    while (i <= text.size()) {
        size_t e = text.find('\n', i);
        std::string line = text.substr(i, e == std::string::npos ? std::string::npos : e - i);
        if (e == std::string::npos) {
            e = text.size();
        }
        // leading whitespace of this paragraph determines the continuation indent
        int          indent = 0;
        while (indent < int(line.size()) && line[size_t(indent)] == ' ') {
            indent++;
        }
        // split the paragraph into words
        std::vector<std::string> words;
        size_t                   j = 0;
        while (j < line.size()) {
            while (j < line.size() && line[j] == ' ') {
                j++;
            }
            if (j >= line.size()) {
                break;
            }
            size_t k = j;
            while (k < line.size() && line[k] != ' ') {
                k++;
            }
            words.push_back(line.substr(j, k - j));
            j = k;
        }
        std::string cur;
        bool        first = true;
        for (const auto& w : words) {
            if (cur.empty()) {
                cur = std::string(size_t(indent), ' ');
                cur += w;
            } else if (int(cur.size()) + 1 + int(w.size()) <= width) {
                cur += " ";
                cur += w;
            } else {
                if (!first || true) {
                    out += cur;
                    out += "\n";
                }
                cur = std::string(size_t(indent), ' ');
                cur += w;
            }
            first = false;
        }
        if (!cur.empty()) {
            out += cur;
            out += "\n";
        } else if (words.empty()) {
            out += std::string(size_t(indent), ' ');
            out += "\n";
        }
        i = e + 1;
        if (e == text.size()) {
            break;
        }
    }
    return out;
}

