                                    "gmx::FilePtr gmx::openFileWithBackup(const std::string&, "
                                    "const std::string&)"};
const Source SRC_FFLIB           = {"src/gromacs/gmxpreprocess/fflibutil.cpp", 127,
                                    "std::vector<gmx::DataFileInfo> fflib_enumerate_forcefields()"};

static void printErrorBlock(const Source& s, const std::string& kind, const std::string& message)
{
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "-------------------------------------------------------\n");
    std::fprintf(stderr, "Program:     %s, version %s\n", rt.label.c_str(),
                 GMX_VERSION.c_str());
    std::fprintf(stderr, "Source file: %s (line %d)\n", s.file, s.line);
    std::fprintf(stderr, "Function:    %s\n", s.func);
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "%s:\n", kind.c_str());
    std::fputs(wrapText(message).c_str(), stderr);
    std::fprintf(stderr, "\n");
    std::fprintf(stderr,
                 "For more information and tips for troubleshooting, please check the GROMACS\n");
    std::fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
    std::fprintf(stderr, "-------------------------------------------------------\n");
}

void reportError(const Source& s, const std::string& kind, const std::string& message)
{
    printErrorBlock(s, kind, message);
    std::exit(1);
}

void ErrorSink::add(const std::string& optionName, const std::string& msg)
{
    entries.push_back(OptError{optionName, msg});
}

void ErrorSink::addNoOpt(const std::string& msg)
{
    entries.push_back(OptError{std::string(), msg});
}

std::string ErrorSink::text() const
{
    std::string out = "Invalid command-line options\n";
    for (const auto& e : entries) {
        if (!e.optionName.empty()) {
            out += format("  In command-line option -%s\n", e.optionName.c_str());
        }
        out += e.message;
        out += "\n";
    }
    return out;
}

void throwOptErrors(const ErrorSink& e, const Source& s)
{
    reportError(s, "Error in user input", e.text());
}

// ---------------------------------------------------------------------------
// startup output
// ---------------------------------------------------------------------------
void printStartHeader()
{
    std::fprintf(stderr, "       :-) GROMACS - %s, %s (-:\n", rt.label.c_str(),
                 GMX_VERSION.c_str());
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "Executable:   %s\n", rt.exePath.c_str());
    std::fprintf(stderr, "Data prefix:  %s\n", GMX_DATAPREFIX);
    std::fprintf(stderr, "Working dir:  %s\n", rt.workingDir.c_str());
    std::fprintf(stderr, "Command line:\n");
    std::fprintf(stderr, "  %s\n", rt.commandLine.c_str());
    std::fprintf(stderr, "\n");
}

void printQuote()
{
    if (rt.quiet) {
        return;
    }
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "GROMACS reminds you: \"%s\" (%s)\n", randomQuote().c_str(),
                 quoteAuthor().c_str());
    std::fprintf(stderr, "\n");
}

void printHelpText(const std::string& text)
{
    std::fputs(text.c_str(), stdout);
}

