namespace gmx {

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------
static bool allDashes(const std::string& s)
{
    if (s.empty()) {
        return false;
    }
    for (char c : s) {
        if (c != '-') {
            return false;
        }
    }
    return true;
}

// Tokens that cannot be option names: numbers, "-" and "--".
static bool isValueish(const std::string& s)
{
    if (s.empty()) {
        return false;
    }
    if (allDashes(s)) {
        return true;
    }
    if (s[0] != '-') {
        return false;
    }
    const char* p = s.c_str();
    char*       end = nullptr;
    strtod(p, &end);
    return *end == '\0';
}

static bool isOptionLike(const std::string& s)
{
    return s.size() > 1 && s[0] == '-' && !isValueish(s);
}

static std::string stripDashes(const std::string& s)
{
    size_t i = 0;
    while (i < s.size() && s[i] == '-') {
