    {"nice", OK_INT, false},      {"backup", OK_BOOL, true},
    {"debug", OK_BOOL, true},
};
static const int kNumGlobalDefs = int(sizeof(kGlobalDefs) / sizeof(kGlobalDefs[0]));

static const GlobalDef* findGlobal(const std::string& name)
{
    for (int i = 0; i < kNumGlobalDefs; ++i) {
        if (name == kGlobalDefs[i].name) {
            return &kGlobalDefs[i];
        }
    }
    return nullptr;
