static bool isRecognizedExtension(const std::string& e)
{
    static const char* kExt[] = {"brk", "cpt", "csv", "dat", "edi", "edr", "ent", "eps",
                                 "esp", "g96", "gro", "h5md", "inp", "itp", "log", "m2p",
                                 "mdp", "mtx", "ndx", "out", "pdb", "pqr", "rtp", "tex",
                                 "tng", "top", "tpr", "trr", "xpm", "xtc", "xvg"};
    for (const char* x : kExt) {
        if (e == x) {
            return true;
        }
