    return false;
}

static std::vector<std::string> splitList(const char* s)
{
    std::vector<std::string> r;
    if (s == nullptr) {
        return r;
    }
    const char* p = s;
    while (*p) {
        while (*p == ' ' || *p == ',') {
            p++;
        }
        const char* q = p;
        while (*q && *q != ' ' && *q != ',') {
            q++;
        }
        if (q > p) {
            r.push_back(std::string(p, q - p));
        }
        p = q;
    }
    return r;
}

// Extension completion for a file option value.  Returns "" when the value is
// accepted (setting *resolved), otherwise the error message.
static std::string checkFileValue(const std::string& value, const std::vector<std::string>& exts,
                                  std::string* resolved)
{
    *resolved = value;
    std::string ext = tolower(fileExtension(value));
    bool        allowed = false;
    for (const auto& e : exts) {
        if (tolower(e) == ext) {
            allowed = true;
        }
    }
    std::string list;
    for (size_t i = 0; i < exts.size(); ++i) {
        list += (i ? ", " : "  ");
        list += exts[i];
    }
    if (allowed) {
        if (isRegularFile(value)) {
            return "";
        }
        if (fileExists(value)) {
            return format("Failed to access file '%s'.\nThe file is not a regular file.",
                          value.c_str());
        }
        return format("File '%s' does not exist or is not accessible.\n"
                      "The file could not be opened.\n"
                      "  Reason: No such file or directory\n"
                      "  (call to fopen() returned error code 2)",
                      value.c_str());
    }
    if (!ext.empty() && isRecognizedExtension(ext)) {
        return format("File name '%s' cannot be used for this option.\n"
                      "Only the following extensions are possible:\n%s",
                      value.c_str(), list.c_str());
    }
    if (fileExists(value)) {
        return format("File '%s' cannot be used by GROMACS because it does not have a\n"
                      "recognizable extension.\n"
                      "The following extensions are possible for this option:\n%s",
                      value.c_str(), list.c_str());
    }
    for (const auto& e : exts) {
        std::string cand = value + "." + e;
        if (isRegularFile(cand)) {
            *resolved = cand;
            return "";
        }
    }
    return format("File '%s' does not exist or is not accessible.\n"
                  "The following extensions were tried to complete the file name:\n%s",
                  value.c_str(), list.c_str());
}

// ---------------------------------------------------------------------------
// value conversion of a single option
// ---------------------------------------------------------------------------
struct ConvResult {
    bool  ok = false;
    std::string error;
    std::string resolved; // file name after extension completion
};

static int maxValueCount(OptKind kind)
{
    switch (kind) {
    case OK_MFILEIN:
    case OK_MFILEOUT:
    case OK_SELECTION: return 1 << 20;
    case OK_VECTOR: return 3;
    default: return 1;
    }
}

static int minValueCount(OptKind kind)
{
    switch (kind) {
    case OK_BOOL:
    case OK_SELECTION: return 0;
    case OK_VECTOR: return 0;
    default: return 1;
    }
}

static ConvResult convertValue(const std::string& optName, const GmxOpt* o,
                              const std::string& raw)
{
    ConvResult r;
    switch (o->kind) {
    case OK_BOOL: {
        std::string v = raw;
        for (auto& c : v) {
            c = char(tolower((unsigned char)c));
        }
        if (v == "1" || v == "yes" || v == "true" || v == "0" || v == "no" || v == "false") {
            r.ok = true;
        } else {
            r.error = "supported values are: 1, 0, yes, no, true, false";
        }
        break;
    }
    case OK_INT: {
        int v = 0;
        std::string e;
        if (raw.empty() || raw[0] != '-') {
            // the nice level only accepts negative values
            e = "expected an integer";
            r.ok = false;
            r.error = e;
            break;
        }
        e = convertInt(raw, &v);
        if (e.empty()) {
            r.ok = true;
        } else {
            r.error = e;
        }
        break;
    }
    case OK_TIME:
    case OK_REAL: {
        double v = 0;
        std::string e = convertReal(raw, &v);
        if (e.empty()) {
            r.ok = true;
        } else {
            r.error = e;
        }
        break;
    }
    case OK_ENUM: {
        auto vals = splitList(o->enums);
        for (const auto& v : vals) {
            if (v == raw) {
                r.ok = true;
                break;
            }
        }
        if (!r.ok) {
            r.error = format("Allowed values: %s.", o->enums ? o->enums : "");
        }
        break;
    }
    case OK_STRING:
    case OK_SELECTION:
    case OK_VECTOR: {
        double d = 0;
        std::string e = convertReal(raw, &d);
        if (e.empty()) {
            r.ok = true;
        } else {
            r.error = e;
        }
        break;
    }
    case OK_SELFILE: {
        if (isRegularFile(raw)) {
            r.ok = true;
        } else {
            r.error = format("Error in parsing selections from file '%s'\n"
                             "  Could not open file '%s'\n"
                             "    Reason: No such file or directory\n"
                             "    (call to fopen() returned error code 2)",
                             raw.c_str(), raw.c_str());
        }
        break;
    }
    case OK_FILEIN:
    case OK_MFILEIN:
    case OK_FILEOUT:
    case OK_MFILEOUT: {
        std::vector<std::string> exts = splitList(o->exts);
        std::string              e = checkFileValue(raw, exts, &r.resolved);
        if (e.empty()) {
            r.ok = true;
        } else {
            r.error = e;
        }
        break;
    }
    }
    return r;
}

// ---------------------------------------------------------------------------
// global options
// ---------------------------------------------------------------------------
static bool setBoolean(bool* target, bool value) { *target = value; return true; }

int parseGlobalOptions(std::vector<std::string> args, GlobalOpts* go,
                       std::vector<std::string>* rest)
{
    ErrorSink err;
    size_t    i = 0;
    bool      stop = false;
    while (i < args.size()) {
        const std::string& a = args[i];
        if (!isOptionLike(a)) {
            break; // this is the command name
        }
        std::string          name = stripDashes(a);
        const GlobalDef*     def = findGlobal(name);
        bool                 negate = false;
        if (!def && name.compare(0, 2, "no") == 0) {
            def = findGlobal(name.substr(2));
            if (def) {
                negate = true;
            }
        }
        if (!def) {
            err.addNoOpt(format("Unknown command-line option %s", a.c_str()));
            i++;
            continue;
        }
        i++;
        switch (def->kind) {
        case OK_BOOL: {
            if (i < args.size() && isValueish(args[i])) {
                err.add(def->name,
                        format("Invalid value: '%s'; supported values are: 1, 0, yes, no, true, "
                               "false",
                               args[i].c_str()));
                i++;
                break;
            }
            bool val = !negate;
            if (def->name == std::string("h")) {
                setBoolean(&go->help, val);
            } else if (def->name == std::string("quiet")) {
                setBoolean(&go->quiet, val);
            } else if (def->name == std::string("version")) {
                setBoolean(&go->version, val);
            } else if (def->name == std::string("copyright")) {
                setBoolean(&go->copyright, val);
            } else if (def->name == std::string("backup")) {
                setBoolean(&go->backup, val);
            } else if (def->name == std::string("debug")) {
                setBoolean(&go->debug, val);
            }
            break;
        }
        case OK_INT: {
            int    nvalid = 0;
            int    nconsumed = 0;
            while (i < args.size()) {
                if (!isValueish(args[i])) {
                    break;
                }
                const std::string tok = args[i];
                i++;
                nconsumed++;
                int         v = 0;
                std::string e;
                if (tok[0] != '-') {
                    // only negative values are accepted, no message
                } else {
                    e = convertInt(tok, &v);
                }
                if (e.empty()) {
                    nvalid++;
                    if (nvalid > 1) {
                        err.add(def->name, "Too many values");
                    } else {
                        go->nice = v;
                        go->niceGiven = true;
                    }
                } else {
                    err.add(def->name, format("Invalid value: '%s'; %s", tok.c_str(), e.c_str()));
                    stop = true;
                    break;
                }
            }
            if (nvalid < 1) {
                err.add(def->name, "Too few (valid) values");
            }
            break;
        }
        default: break;
        }
        if (stop) {
            break;
        }
    }
    if (!err.empty()) {
        throwOptErrors(err, SRC_CMDLINE_PARSE);
    }
    if (rest != nullptr) {
        rest->assign(args.begin() + long(i), args.end());
    }
    return int(i);
}

// ---------------------------------------------------------------------------
// command options
// ---------------------------------------------------------------------------
const GmxOpt* findOpt(const GmxModule* mod, const std::string& name)
{
    for (int i = 0; i < mod->nopts; ++i) {
        if (name == mod->opts[i]->name) {
            return mod->opts[i];
        }
    }
    return nullptr;
}

OptValues parseCommandOptions(const GmxModule* mod, const std::vector<std::string>& args)
{
    OptValues v;
    ErrorSink err;
    size_t    i = 0;
    while (i < args.size()) {
        const std::string& a = args[i];
        if (!isOptionLike(a)) {
            // positional argument
            err.addNoOpt(format("Positional argument '%s' cannot be accepted. Perhaps you forgot "
                                "to put a hyphen before an option name.",
                                a.c_str()));
            i++;
            continue;
        }
        std::string name = stripDashes(a);
        bool        negate = false;
        const GmxOpt* o = findOpt(mod, name);
        if (!o && name.compare(0, 2, "no") == 0) {
            o = findOpt(mod, name.substr(2));
            if (o && o->kind != OK_BOOL) {
                o = nullptr;
            }
            if (o) {
                negate = true;
            }
        }
        if (!o) {
            err.addNoOpt(format("Unknown command-line option %s", a.c_str()));
            i++;
            continue;
        }
        i++;
        v.order.push_back(name);
        if (o->kind == OK_BOOL) {
            if (i < args.size() && isValueish(args[i])) {
                err.add(o->name,
                        format("Invalid value: '%s'; supported values are: 1, 0, yes, no, true, "
                               "false",
                               args[i].c_str()));
                i++;
                continue;
            }
            v.raw[o->name].push_back(negate ? "no" : "yes");
            continue;
        }
        int         nvalid = 0;
        int         nconsumed = 0;
        int         maxv = maxValueCount(o->kind);
        while (i < args.size()) {
            if (!isValueish(args[i])) {
                break;
            }
            std::string tok = args[i];
            i++;
            nconsumed++;
            ConvResult cr = convertValue(o->name, o, tok);
            if (cr.ok) {
                if (nvalid >= maxv) {
                    err.add(o->name, "Too many values");
                } else {
                    nvalid++;
                    if (o->kind == OK_FILEIN || o->kind == OK_MFILEIN) {
                        v.raw[o->name].push_back(cr.resolved);
                    } else {
                        v.raw[o->name].push_back(tok);
                    }
                }
            } else {
                err.add(o->name,
                        format("Invalid value: %s%s", cr.error.substr(0, 20).empty() ? "" : "",
                               tok.c_str()));
                err.entries.back().message = "Invalid value: ";
                err.entries.back().message += o->kind == OK_ENUM ? tok : ("'" + tok + "'");
                err.entries.back().message += o->kind == OK_ENUM ? ("." + cr.error.substr(0, 0) + "") : "";
                err.entries.back().message = format("Invalid value: %s", tok.c_str());
                if (o->kind == OK_ENUM) {
                    err.entries.back().message += ". " + cr.error;
                } else if (o->kind == OK_SELFILE) {
                    err.entries.back().message = cr.error;
                } else {
                    err.entries.back().message = format("Invalid value: '%s'; %s", tok.c_str(),
                                                        cr.error.c_str());
                }
            }
            // vector options report the expected count once all values are read
        }
        if (o->kind == OK_VECTOR) {
            if (nvalid > 0 && nvalid != 1 && nvalid != 3) {
                err.add(o->name, format("Expected 1 or 3 values, got %d", nvalid));
            }
        }
        if (nvalid < minValueCount(o->kind)) {
            err.add(o->name, "Too few (valid) values");
        }
    }
    if (!err.empty()) {
        throwOptErrors(err, SRC_CMDLINE_PARSE);
    }
    return v;
}

// ---------------------------------------------------------------------------
void validateOptions(const GmxModule* mod, const OptValues& v)
{
    std::string msg;
    for (int i = 0; i < mod->nreqs; ++i) {
        const GmxReq& r = *mod->reqs[i];
        if (v.given(r.name)) {
            continue;
        }
        std::string stem = r.stem;
        bool        found = false;
        std::vector<std::string> exts = splitList(r.exts.c_str());
        for (const auto& e : exts) {
            if (isRegularFile(stem + "." + tolower(e))) {
                found = true;
            }
        }
        if (found) {
            continue;
        }
        std::string list;
        for (size_t j = 0; j < exts.size(); ++j) {
            list += (j ? ", " : "  ");
            list += exts[j];
        }
        msg += format("  In option %s\n", r.name);
        msg += wrapText(format("Required option was not provided, and the default file '%s' does "
                               "not exist or is not accessible.\n"
                               "The following extensions were tried to complete the file name:\n%s",
                               stem.c_str(), list.c_str()),
                        74);
        msg += "\n";
    }
    if (!msg.empty()) {
        reportError(SRC_OPTIONS_FINISH, "Error in user input", "Invalid input values\n" + msg);
    }
}

// ---------------------------------------------------------------------------
std::string OptValues::str(const std::string& n, const std::string& dflt) const
{
    auto it = raw.find(n);
    if (it == raw.end() || it->second.empty()) {
        return dflt;
    }
    return it->second.back();
}

double OptValues::real(const std::string& n, double dflt) const
{
    auto it = raw.find(n);
    if (it == raw.end() || it->second.empty()) {
        return dflt;
    }
    double v = 0;
    convertReal(it->second.back(), &v);
    return v;
}

long OptValues::integer(const std::string& n, long dflt) const
{
    auto it = raw.find(n);
    if (it == raw.end() || it->second.empty()) {
        return dflt;
    }
    int v = 0;
    convertInt(it->second.back(), &v);
    return long(v);
}

} // namespace gmx
