#include "gmx.h"
#include <unistd.h>
#include <limits.h>
#include <sys/stat.h>

namespace gmx {

static std::string readlinkPath(const std::string& p)
{
    char   buf[PATH_MAX];
    ssize_t n = ::readlink(p.c_str(), buf, sizeof(buf) - 1);
    if (n <= 0) {
        return std::string();
    }
    buf[n] = '\0';
    return std::string(buf);
}

// Reproduce the path shown after "Executable:".
static std::string exePath(const char* argv0)
{
    std::string arg = argv0;
    std::string path = arg;
    if (arg.find('/') == std::string::npos) {
        // search PATH
        const char* env = ::getenv("PATH");
        if (env != nullptr) {
            std::string            dirs = env;
            size_t                 i = 0;
            while (true) {
                size_t j = dirs.find(':', i);
                std::string d = dirs.substr(i, j == std::string::npos ? std::string::npos : j - i);
                if (d.empty()) {
                    d = ".";
                }
                std::string cand = d + "/" + arg;
                if (fileExists(cand)) {
                    path = cand;
                    break;
                }
                if (j == std::string::npos) {
                    break;
                }
                i = j + 1;
            }
        }
    }
    if (!path.empty() && path[0] != '/') {
        char buf[PATH_MAX];
        if (::getcwd(buf, sizeof(buf)) != nullptr) {
            path = std::string(buf) + "/" + path;
        }
    }
    // resolve symlinks
    std::string cur = path;
    for (int guard = 0; guard < 32; ++guard) {
        std::string target = readlinkPath(cur);
        if (target.empty()) {
            break;
        }
        if (target[0] != '/') {
            std::string dir = cur;
            size_t      i = dir.find_last_of('/');
            dir = (i == std::string::npos ? std::string() : dir.substr(0, i + 1));
            cur = dir + target;
        } else {
            cur = target;
        }
    }
    return cur;
}

static std::string mainHelp()
{
    const char* h = findTopicHelp("");
    return h == nullptr ? std::string() : h;
}

static std::string join(const std::vector<std::string>& v, size_t from)
{
    std::string s;
    for (size_t i = from; i < v.size(); ++i) {
        if (!s.empty()) {
            s += " ";
        }
        s += v[i];
    }
    return s;
}

} // namespace gmx

int main(int argc, char** argv)
{
    using namespace gmx;
    std::vector<std::string> args;
    for (int i = 1; i < argc; ++i) {
        args.push_back(argv[i]);
    }
    rt.progName = basename(argv[0]);
    rt.exePath = exePath(argv[0]);
    {
        char buf[PATH_MAX];
        if (::getcwd(buf, sizeof(buf)) != nullptr) {
            rt.workingDir = buf;
        }
    }
    rt.commandLine = rt.progName + (args.empty() ? std::string() : " " + join(args, 0));
    rt.label = rt.progName;
    rt.backup = true;

    GlobalOpts go;
    std::vector<std::string> rest;
    parseGlobalOptions(args, &go, &rest);
    rt.quiet = go.quiet;
    rt.backup = go.backup;

    bool helpWanted = go.help;
    if (!helpWanted && !go.version && !rest.empty()) {
        const GmxModule* m = findModule(rest[0].c_str());
        if (m != nullptr) {
            rt.label = std::string("gmx ") + m->name;
        }
    }
    if (!rt.quiet) {
        printStartHeader();
    }
    if (go.version) {
        printVersionInfo();
        return 0;
    }
    if (go.copyright) {
        printCopyright();
    }
    if (helpWanted || rest.empty()) {
        printHelpText(mainHelp());
        printQuote();
        return 0;
    }
    const GmxModule* mod = findModule(rest[0].c_str());
    if (mod == nullptr) {
        reportError(SRC_MODULEMANAGER, "Error in user input",
                    format("'%s' is not a GROMACS command.", rest[0].c_str()));
    }
    std::vector<std::string> cmdArgs(rest.begin() + 1, rest.end());
    return runCommand(mod, cmdArgs);
