static bool findLibraryFile(const char* name, std::string* found)
{
    // search the current directory and the default data directories
    if (isRegularFile(name)) {
        *found = name;
        return true;
    }
    const char* env = ::getenv("GMXLIB");
    std::vector<std::string> dirs;
    if (env != nullptr) {
        dirs.push_back(env);
