// ---------------------------------------------------------------------------
// coordinate file readers
// ---------------------------------------------------------------------------
struct Atom {
    int         resnr = 0;
    std::string resname;
    std::string atomname;
    int         atomnr = 0;
    double      x[3] = {0, 0, 0};
    double      v[3] = {0, 0, 0};
    bool        hasVel = false;
};
struct Frame {
    std::string      title;
    int              natoms = 0;
    std::vector<Atom> atoms;
    double           box[9] = {0, 0, 0, 0, 0, 0, 0, 0, 0};
    int              nbox = 0;
    long             step = 0;
    double           time = 0;
    double           lambda = 0;
};

static std::vector<std::string> readFileLines(const std::string& name, bool* ok)
{
    std::vector<std::string> lines;
    FILE*                    f = std::fopen(name.c_str(), "r");
    *ok = (f != nullptr);
    if (f == nullptr) {
        return lines;
    }
    char buf[4096];
    while (std::fgets(buf, sizeof(buf), f) != nullptr) {
        std::string s = buf;
        while (!s.empty() && (s.back() == '\n' || s.back() == '\r')) {
            s.pop_back();
        }
        lines.push_back(s);
    }
    std::fclose(f);
    return lines;
}

// read a gro or g96 file
static void readGroFile(const std::string& name, const char* display,
                        std::vector<Frame>* frames, long* step, double* t0)
{
    bool ok = false;
    auto lines = readFileLines(name, &ok);
    if (!ok) {
        reportError(SRC_FUTIL_OPEN, "File input/output error", name);
    }
    bool   g96 = name.size() > 4 && name.substr(name.size() - 4) == ".g96";
    size_t i = 0;
    if (lines.empty()) {
        reportError(SRC_GROIO, "Fatal error",
                    format("Something is wrong in the coordinate formatting of file %s. Note\n"
                           "that gro is fixed format (see the manual)",
                           display));
    }
    while (i < lines.size()) {
        Frame fr;
        fr.title = lines[i];
        i++;
        if (i >= lines.size()) {
            break;
        }
        int n = 0;
        if (sscanf(lines[i].c_str(), "%d", &n) != 1 || n < 0) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. "
                               "Note\nthat gro is fixed format (see the manual)",
                               display));
        }
        fr.natoms = n;
        i++;
        if (i + size_t(n) > lines.size()) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. "
                               "Note\nthat gro is fixed format (see the manual)",
                               display));
        }
        bool vel = false;
        for (int a = 0; a < n; ++a) {
            const std::string& l = lines[i + size_t(a)];
            Atom               at;
            if (int(l.size()) < 44) {
                reportError(SRC_GROIO, "Fatal error",
                            format("Something is wrong in the coordinate formatting of file %s. "
                                   "Note\nthat gro is fixed format (see the manual)",
                                   display));
            }
            char rn[16], an[16];
            if (sscanf(l.c_str(), "%5d%5s%5s%5d", &at.resnr, rn, an, &at.atomnr) != 4) {
                reportError(SRC_GROIO, "Fatal error",
                            format("Something is wrong in the coordinate formatting of file %s. "
                                   "Note\nthat gro is fixed format (see the manual)",
                                   display));
            }
            at.resname = rn;
            at.atomname = an;
            if (int(l.size()) >= 69) {
                vel = true;
            }
            if (g96) {
                if (sscanf(l.c_str() + 20, "%15lf%15lf%15lf", &at.x[0], &at.x[1], &at.x[2]) != 3) {
                    reportError(SRC_GROIO, "Fatal error",
                                format("Something is wrong in the coordinate formatting of file "
                                       "%s. Note\nthat gro is fixed format (see the manual)",
                                       display));
                }
                if (int(l.size()) >= 65 && sscanf(l.c_str() + 65, "%15lf%15lf%15lf", &at.v[0],
                                                  &at.v[1], &at.v[2]) == 3) {
                    at.hasVel = true;
                }
            } else {
                if (sscanf(l.c_str() + 20, "%8lf%8lf%8lf", &at.x[0], &at.x[1], &at.x[2]) != 3) {
                    reportError(SRC_GROIO, "Fatal error",
                                format("Something is wrong in the coordinate formatting of file "
                                       "%s. Note\nthat gro is fixed format (see the manual)",
                                       display));
                }
                if (int(l.size()) >= 69 && sscanf(l.c_str() + 44, "%8lf%8lf%8lf", &at.v[0],
                                                  &at.v[1], &at.v[2]) == 3) {
                    at.hasVel = true;
                }
            }
            fr.atoms.push_back(at);
        }
        i += size_t(n);
        if (i >= lines.size()) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. Note\n"
                               "that gro is fixed format (see the manual)",
                               display));
        }
        const std::string& bl = lines[i];
        double             v[9];
        int                nb = 0;
        if (g96) {
            for (int k = 0; k < 9; ++k) {
                if (sscanf(bl.c_str() + 15 * k, "%15lf%n", &v[k], &nb) != 1) {
                    break;
                }
            }
        } else {
            for (int k = 0; k < 9; ++k) {
                if (sscanf(bl.c_str() + 10 * k, "%10lf%n", &v[k], &nb) != 1) {
                    break;
                }
            }
        }
        fr.nbox = (nb > 0) ? 3 : 0;
        if (nb > 0) {
            for (int k = 0; k < 3; ++k) {
                fr.box[k] = v[k];
            }
        }
        if (nb == 9) {
            for (int k = 0; k < 9; ++k) {
                fr.box[k] = v[k];
            }
            fr.nbox = 9;
        }
        i++;
        (void)vel;
        frames->push_back(fr);
        if (step != nullptr) {
            *step = fr.step;
        }
        if (t0 != nullptr) {
            *t0 = fr.time;
        }
    }
}

