// ---------------------------------------------------------------------------
// selections
// ---------------------------------------------------------------------------
struct SelTok {
    std::string text;
};
static void selTokenize(const std::string& s, std::vector<SelTok>* out)
{
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace((unsigned char)s[i])) {
            i++;
        }
        if (i >= s.size()) {
            break;
        }
        if (s[i] == '"' || s[i] == '\'') {
            char q = s[i];
            size_t j = i + 1;
            while (j < s.size() && s[j] != q) {
                j++;
            }
            out->push_back(SelTok{s.substr(i, j - i + 1)});
            i = (j < s.size()) ? j + 1 : j;
            continue;
        }
        size_t j = i;
        while (j < s.size() && !isspace((unsigned char)s[j])) {
            j++;
        }
        out->push_back(SelTok{s.substr(i, j - i)});
        i = j;
    }
}

static bool isSelKeywordWithArg(const std::string& t)
{
    static const char* k[] = {"atomnr", "mol",     "molecule", "molindex", "resid",
                              "residue", "resindex", "resnr",   "beta",    "betafactor",
                              "charge",  "mass",    "mindistance", "occupancy", "x",
                              "y",       "z",       "altloc",  "atomname", "atomtype",
                              "chain",   "insertcode", "name", "pdbatomname", "pdbname",
                              "resname", "type",    "merge",   "group",    "atom",
                              "insert",  "positions", "position"};
    for (const char* x : k) {
        if (t == x) {
            return true;
        }
    }
    return false;
}

static bool isSelOperator(const std::string& t)
{
    return t == "and" || t == "or" || t == "not" || t == "!" || t == "&&" || t == "||";
}

// Returns the index of the first offending token, or -1 when the selection
// looks syntactically valid.
static int selParse(const std::vector<SelTok>& t, int* pos)
{
    int i = *pos;
    while (true) {
        if (i >= int(t.size())) {
            *pos = i;
            return i;
        }
        const std::string& tok = t[size_t(i)];
        if (tok == "(") {
            i++;
            int save = i;
            int r = selParse(t, &i);
            if (r >= 0) {
                *pos = r;
                return r;
            }
            i = save;
            if (i >= int(t.size()) || t[size_t(i)] != ")") {
                *pos = i;
                return i;
            }
            i++;
        } else if (tok == "within" || tok == "same" || tok == "cog" || tok == "com"
                   || tok == "insolidangle" || tok == "permute") {
            i++;
            while (i < int(t.size()) && !isSelOperator(t[size_t(i)]) && t[size_t(i)] != "(") {
                i++;
            }
        } else if (isSelKeywordWithArg(tok)) {
            i++;
            if (i >= int(t.size()) || isSelOperator(t[size_t(i)]) || t[size_t(i)] == ")") {
                *pos = i;
                return i;
            }
            i++;
            while (i < int(t.size()) && !isSelOperator(t[size_t(i)]) && t[size_t(i)] != "("
                   && t[size_t(i)] != ")" && !isSelKeywordWithArg(t[size_t(i)])) {
                i++;
            }
        } else if (tok == "all" || tok == "none") {
            i++;
        } else if (tok == "to" || tok == "of" || tok == "from" || tok == "as" || tok == "cutoff"
                   || tok == "pbc" || tok == "center" || tok == "span") {
            i++;
            if (i >= int(t.size()) || isSelOperator(t[size_t(i)])) {
                *pos = i;
                return i;
            }
            i++;
        } else {
            i++;
        }
        if (i < int(t.size()) && isSelOperator(t[size_t(i)])) {
            i++;
            continue;
        }
        break;
    }
    *pos = i;
    return -1;
}

static void parseSelections(const GmxModule* mod, OptValues* v, ErrorSink* err)
{
    // every <selection> option must have at least one value
    for (int i = 0; i < mod->nopts; ++i) {
        const GmxOpt* o = mod->opts[i];
        if (o->kind != OK_SELECTION) {
            continue;
        }
        auto it = v->raw.find(o->name);
        int  count = (it == v->raw.end()) ? 0 : int(it->second.size());
        if (count == 0) {
            if (it == v->raw.end()) {
                continue;
            }
        }
        if (it == v->raw.end()) {
            continue;
        }
        for (const auto& sel : it->second) {
            std::vector<SelTok> toks;
            selTokenize(sel, &toks);
            int pos = 0;
            int r = selParse(toks, &pos);
            if (r >= 0 || pos < int(toks.size())) {
                const std::string& bad = (pos < int(toks.size())) ? toks[size_t(pos)].text
                                                                 : std::string();
                err->add(o->name,
                         format("Invalid selection '%s'\n  Near '%s'\n    syntax error",
                                sel.c_str(), bad.c_str()));
            }
        }
    }
}

