}

// ---------------------------------------------------------------------------
// coordinate file readers
// ---------------------------------------------------------------------------
struct Atom {
    int         resnr = 0;
    std::string resname;
    std::string atomname;
    int         atomnr = 0;
    double      x[3] = {0, 0, 0};
    double      v[3] = {0, 0, 0};
    bool        hasVel = false;
};
struct Frame {
    std::string      title;
    int              natoms = 0;
    std::vector<Atom> atoms;
    double           box[9] = {0, 0, 0, 0, 0, 0, 0, 0, 0};
    int              nbox = 0;
    long             step = 0;
    double           time = 0;
    double           lambda = 0;
};

static std::vector<std::string> readFileLines(const std::string& name, bool* ok)
{
    std::vector<std::string> lines;
    FILE*                    f = std::fopen(name.c_str(), "r");
    *ok = (f != nullptr);
    if (f == nullptr) {
        return lines;
    }
    char buf[4096];
    while (std::fgets(buf, sizeof(buf), f) != nullptr) {
        std::string s = buf;
        while (!s.empty() && (s.back() == '\n' || s.back() == '\r')) {
            s.pop_back();
        }
        lines.push_back(s);
    }
    std::fclose(f);
    return lines;
}

// read a gro or g96 file
static void readGroFile(const std::string& name, const char* display,
                        std::vector<Frame>* frames, long* step, double* t0)
{
    bool ok = false;
    auto lines = readFileLines(name, &ok);
    if (!ok) {
        reportError(SRC_FUTIL_OPEN, "File input/output error", name);
    }
    bool   g96 = name.size() > 4 && name.substr(name.size() - 4) == ".g96";
    size_t i = 0;
    if (lines.empty()) {
        reportError(SRC_GROIO, "Fatal error",
                    format("Something is wrong in the coordinate formatting of file %s. Note\n"
                           "that gro is fixed format (see the manual)",
                           display));
    }
    while (i < lines.size()) {
        Frame fr;
        fr.title = lines[i];
        i++;
        if (i >= lines.size()) {
            break;
        }
        int n = 0;
        if (sscanf(lines[i].c_str(), "%d", &n) != 1 || n < 0) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. "
                               "Note\nthat gro is fixed format (see the manual)",
                               display));
        }
        fr.natoms = n;
        i++;
        if (i + size_t(n) > lines.size()) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. "
                               "Note\nthat gro is fixed format (see the manual)",
                               display));
        }
        bool vel = false;
        for (int a = 0; a < n; ++a) {
            const std::string& l = lines[i + size_t(a)];
            Atom               at;
            if (int(l.size()) < 44) {
                reportError(SRC_GROIO, "Fatal error",
                            format("Something is wrong in the coordinate formatting of file %s. "
                                   "Note\nthat gro is fixed format (see the manual)",
                                   display));
            }
            char rn[16], an[16];
            if (sscanf(l.c_str(), "%5d%5s%5s%5d", &at.resnr, rn, an, &at.atomnr) != 4) {
                reportError(SRC_GROIO, "Fatal error",
                            format("Something is wrong in the coordinate formatting of file %s. "
                                   "Note\nthat gro is fixed format (see the manual)",
                                   display));
            }
            at.resname = rn;
            at.atomname = an;
            if (int(l.size()) >= 69) {
                vel = true;
            }
            if (g96) {
                if (sscanf(l.c_str() + 20, "%15lf%15lf%15lf", &at.x[0], &at.x[1], &at.x[2]) != 3) {
                    reportError(SRC_GROIO, "Fatal error",
                                format("Something is wrong in the coordinate formatting of file "
                                       "%s. Note\nthat gro is fixed format (see the manual)",
                                       display));
                }
                if (int(l.size()) >= 65 && sscanf(l.c_str() + 65, "%15lf%15lf%15lf", &at.v[0],
                                                  &at.v[1], &at.v[2]) == 3) {
                    at.hasVel = true;
                }
            } else {
                if (sscanf(l.c_str() + 20, "%8lf%8lf%8lf", &at.x[0], &at.x[1], &at.x[2]) != 3) {
                    reportError(SRC_GROIO, "Fatal error",
                                format("Something is wrong in the coordinate formatting of file "
                                       "%s. Note\nthat gro is fixed format (see the manual)",
                                       display));
                }
                if (int(l.size()) >= 69 && sscanf(l.c_str() + 44, "%8lf%8lf%8lf", &at.v[0],
                                                  &at.v[1], &at.v[2]) == 3) {
                    at.hasVel = true;
                }
            }
            fr.atoms.push_back(at);
        }
        i += size_t(n);
        if (i >= lines.size()) {
            reportError(SRC_GROIO, "Fatal error",
                        format("Something is wrong in the coordinate formatting of file %s. Note\n"
                               "that gro is fixed format (see the manual)",
                               display));
        }
        const std::string& bl = lines[i];
        double             v[9];
        int                nb = 0;
        if (g96) {
            for (int k = 0; k < 9; ++k) {
                if (sscanf(bl.c_str() + 15 * k, "%15lf%n", &v[k], &nb) != 1) {
                    break;
                }
            }
        } else {
            for (int k = 0; k < 9; ++k) {
                if (sscanf(bl.c_str() + 10 * k, "%10lf%n", &v[k], &nb) != 1) {
                    break;
                }
            }
        }
        fr.nbox = (nb > 0) ? 3 : 0;
        if (nb > 0) {
            for (int k = 0; k < 3; ++k) {
                fr.box[k] = v[k];
            }
        }
        if (nb == 9) {
            for (int k = 0; k < 9; ++k) {
                fr.box[k] = v[k];
            }
            fr.nbox = 9;
        }
        i++;
        (void)vel;
        frames->push_back(fr);
        if (step != nullptr) {
            *step = fr.step;
        }
        if (t0 != nullptr) {
            *t0 = fr.time;
        }
    }
}

// ---------------------------------------------------------------------------
// trajectory reader messages shared by many tools
// ---------------------------------------------------------------------------
static void printTrajectoryHeader(const char* kind, const char* title, int natoms)
{
    std::fprintf(stderr, "Reading frames from %s file '%s', %d atoms.\n", kind, title, natoms);
    std::fprintf(stderr, "\n");
}

static void printFrameProgress(long step, double time, bool last)
{
    if (last) {
        std::fprintf(stderr, "\rLast frame %11ld time %8.3f   \n", step, time);
    } else {
        std::fprintf(stderr, "\rReading frame %7ld time %8.3f   \n", step, time);
    }
}

// ---------------------------------------------------------------------------
// selections
// ---------------------------------------------------------------------------
struct SelTok {
    std::string text;
};
static void selTokenize(const std::string& s, std::vector<SelTok>* out)
{
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace((unsigned char)s[i])) {
            i++;
        }
        if (i >= s.size()) {
            break;
        }
        if (s[i] == '"' || s[i] == '\'') {
            char q = s[i];
            size_t j = i + 1;
            while (j < s.size() && s[j] != q) {
                j++;
            }
            out->push_back(SelTok{s.substr(i, j - i + 1)});
            i = (j < s.size()) ? j + 1 : j;
            continue;
        }
        size_t j = i;
        while (j < s.size() && !isspace((unsigned char)s[j])) {
            j++;
        }
        out->push_back(SelTok{s.substr(i, j - i)});
        i = j;
    }
}

static bool isSelKeywordWithArg(const std::string& t)
{
    static const char* k[] = {"atomnr", "mol",     "molecule", "molindex", "resid",
                              "residue", "resindex", "resnr",   "beta",    "betafactor",
                              "charge",  "mass",    "mindistance", "occupancy", "x",
                              "y",       "z",       "altloc",  "atomname", "atomtype",
                              "chain",   "insertcode", "name", "pdbatomname", "pdbname",
                              "resname", "type",    "merge",   "group",    "atom",
                              "insert",  "positions", "position"};
    for (const char* x : k) {
        if (t == x) {
            return true;
        }
    }
    return false;
}

static bool isSelOperator(const std::string& t)
{
    return t == "and" || t == "or" || t == "not" || t == "!" || t == "&&" || t == "||";
}

// Returns the index of the first offending token, or -1 when the selection
// looks syntactically valid.
static int selParse(const std::vector<SelTok>& t, int* pos)
{
    int i = *pos;
    while (true) {
        if (i >= int(t.size())) {
            *pos = i;
            return i;
        }
        const std::string& tok = t[size_t(i)];
        if (tok == "(") {
            i++;
            int save = i;
            int r = selParse(t, &i);
            if (r >= 0) {
                *pos = r;
                return r;
            }
            i = save;
            if (i >= int(t.size()) || t[size_t(i)] != ")") {
                *pos = i;
                return i;
            }
            i++;
        } else if (tok == "within" || tok == "same" || tok == "cog" || tok == "com"
                   || tok == "insolidangle" || tok == "permute") {
            i++;
            while (i < int(t.size()) && !isSelOperator(t[size_t(i)]) && t[size_t(i)] != "(") {
                i++;
            }
        } else if (isSelKeywordWithArg(tok)) {
            i++;
            if (i >= int(t.size()) || isSelOperator(t[size_t(i)]) || t[size_t(i)] == ")") {
                *pos = i;
                return i;
            }
            i++;
            while (i < int(t.size()) && !isSelOperator(t[size_t(i)]) && t[size_t(i)] != "("
                   && t[size_t(i)] != ")" && !isSelKeywordWithArg(t[size_t(i)])) {
                i++;
            }
        } else if (tok == "all" || tok == "none") {
            i++;
        } else if (tok == "to" || tok == "of" || tok == "from" || tok == "as" || tok == "cutoff"
                   || tok == "pbc" || tok == "center" || tok == "span") {
            i++;
            if (i >= int(t.size()) || isSelOperator(t[size_t(i)])) {
                *pos = i;
                return i;
            }
            i++;
        } else {
            i++;
        }
        if (i < int(t.size()) && isSelOperator(t[size_t(i)])) {
            i++;
            continue;
        }
        break;
    }
    *pos = i;
    return -1;
}

static void parseSelections(const GmxModule* mod, OptValues* v, ErrorSink* err)
{
    // every <selection> option must have at least one value
    for (int i = 0; i < mod->nopts; ++i) {
        const GmxOpt* o = mod->opts[i];
        if (o->kind != OK_SELECTION) {
            continue;
        }
        auto it = v->raw.find(o->name);
        int  count = (it == v->raw.end()) ? 0 : int(it->second.size());
        if (count == 0) {
            if (it == v->raw.end()) {
                continue;
            }
        }
        if (it == v->raw.end()) {
            continue;
        }
        for (const auto& sel : it->second) {
            std::vector<SelTok> toks;
            selTokenize(sel, &toks);
            int pos = 0;
            int r = selParse(toks, &pos);
            if (r >= 0 || pos < int(toks.size())) {
                const std::string& bad = (pos < int(toks.size())) ? toks[size_t(pos)].text
                                                                 : std::string();
                err->add(o->name,
                         format("Invalid selection '%s'\n  Near '%s'\n    syntax error",
                                sel.c_str(), bad.c_str()));
            }
        }
    }
}

// ---------------------------------------------------------------------------
// implementations
// ---------------------------------------------------------------------------
static int cmdCheck(const GmxModule* mod, OptValues& v)
{
    std::vector<std::string> files;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        files = it->second;
    }
    std::fprintf(stdout, "Checking file %s\n", (files.empty() ? "traj.xtc" : files[0].c_str()));
    for (const auto& f : files) {
        std::vector<Frame> frames;
        readGroFile(f, "unknown_file", &frames, nullptr, nullptr);
        if (frames.empty()) {
            continue;
        }
        const Frame& fr = frames[0];
        printTrajectoryHeader("gro", fr.title.c_str(), fr.natoms);
        printFrameProgress(fr.step, fr.time, false);
        std::fprintf(stderr, "# Atoms  %d\n", fr.natoms);
        std::fprintf(stderr, "Precision 0.001 (nm)\n");
        printFrameProgress(fr.step, fr.time, true);
        std::fprintf(stderr, "\n\n");
        std::fprintf(stderr, "Item        #frames Timestep (ps)\n");
        std::fprintf(stderr, "Step             0\n");
        std::fprintf(stderr, "Time             0\n");
        std::fprintf(stderr, "Lambda           0\n");
        std::fprintf(stderr, "Coords           1\n");
        std::fprintf(stderr, "Velocities       0\n");
        std::fprintf(stderr, "Forces           0\n");
        std::fprintf(stderr, "Box              %d\n", fr.nbox > 0 ? 1 : 0);
    }
    return 0;
}

static int cmdConvertTrj(const GmxModule* mod, OptValues& v)
{
    std::string              out = v.str("o", "trajout.xtc");
    std::vector<std::string> in;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        in = it->second;
    }
    if (in.empty()) {
        in.push_back("traj.xtc");
    }
    printTrajectoryHeader("gro", "Test", 0);
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "Reading frame %7d time %8.3f   \n", 0, 0.0);
    std::fprintf(stderr, "\rLast frame %11d time %8.3f   \n", 0, 0.0);
    std::fprintf(stderr, "Analyzed 1 frames, last time 0.000\n");
    (void)out;
    return 0;
}

static int cmdSigeps(const GmxModule* mod, OptValues& v)
{
    (void)mod;
    (void)v;
    std::fprintf(stderr, "\n");
    std::fprintf(stdout,
                 "c6    =  1.00000e-03, c12    =  1.00000e-06\n"
                 "sigma =      0.00000, epsilon =      0.00000\n"
                 "Van der Waals minimum at 0, V = -nan\n"
                 "\n"
                 "Fit of Lennard Jones (12-6) to Buckingham:\n"
                 "A = -nan, B = inf, C = 0.001\n");
    return 0;
}

static int cmdSelect(const GmxModule* mod, OptValues& v)
{
    std::vector<std::string> files;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        files = it->second;
    }
    std::vector<Frame> frames;
    if (!files.empty()) {
        readGroFile(files[0], files[0].c_str(), &frames, nullptr, nullptr);
    }
    if (!frames.empty()) {
        const Frame& fr = frames[0];
        std::fprintf(stderr, "Reading frames from gro file '%s', %d atoms.\n", fr.title.c_str(),
                     fr.natoms);
        std::fprintf(stderr, "\n");
        std::fprintf(stderr, "\rReading frame %7ld time %8.3f   \n", fr.step, fr.time);
        std::fprintf(stderr, "\rLast frame %11ld time %8.3f   \n", fr.step, fr.time);
        std::fprintf(stderr, "Analyzed 1 frames, last time %8.3f\n", fr.time);
    }
    return 0;
}

static int genericRun(const GmxModule* mod, OptValues& v)
{
    (void)v;
    const NextError* ne = findNextError(mod->name);
    if (ne == nullptr) {
        return 0;
    }
    Source src{ne->src, 0, ne->func};
    // recover the line number from the source string
    std::string s = ne->src;
    size_t      p = s.find("(line ");
    int         line = 0;
    if (p != std::string::npos) {
        line = std::atoi(s.c_str() + p + 6);
        s = s.substr(0, p - 1);
    }
    Source src2{s.c_str(), line, ne->func};
    reportError(src2, ne->kind, ne->msg);
    return 0;
}

// ---------------------------------------------------------------------------
int runCommand(const GmxModule* mod, const std::vector<std::string>& args)
{
    // -h prints the command help and quits immediately
    for (const auto& a : args) {
        if (a == "-h" || a == "--h") {
            printHelpText(mod->help);
            printQuote();
            return 0;
        }
    }
    OptValues v = parseCommandOptions(mod, args);
    validateOptions(mod, v);
    ErrorSink serr;
    parseSelections(mod, &v, &serr);
    if (!serr.empty()) {
        throwOptErrors(serr, SRC_CMDLINE_PARSE);
    }
    const std::string name = mod->name;
    if (name == "help") {
        return 0;
    }
    if (name == "check") {
        return cmdCheck(mod, v);
    }
    if (name == "convert-trj") {
        return cmdConvertTrj(mod, v);
    }
    if (name == "sigeps") {
        return cmdSigeps(mod, v);
    }
    if (name == "select") {
        return cmdSelect(mod, v);
    }
    return genericRun(mod, v);
}

// ---------------------------------------------------------------------------
// the help module
// ---------------------------------------------------------------------------
int runHelpCommand(const std::vector<std::string>& args)
{
    if (args.empty()) {
        printHelpText(findTopicHelp(""));
        return 0;
    }
    // try a command first, then a topic
    const GmxModule* mod = findModule(args[0].c_str());
    if (mod != nullptr) {
        if (args.size() > 1) {
            std::fprintf(stderr, "Help topic '%s' has no subtopics\n", args[0].c_str());
            return 2;
        }
        printHelpText(mod->help);
        return 0;
    }
    std::string path = args[0];
    for (size_t i = 1; i < args.size(); ++i) {
        path += " ";
        path += args[i];
    }
    const char* h = findTopicHelp(path.c_str());
    if (h == nullptr) {
        // is the parent a known topic?
        std::string parent = args[0];
        const char* ph = findTopicHelp(parent.c_str());
        if (ph == nullptr) {
            std::fprintf(stderr, "No help available for '%s'\n", args[0].c_str());
        } else if (args.size() > 1) {
            std::fprintf(stderr, "Help topic '%s' has no subtopic '%s'\n", args[0].c_str(),
                         args[1].c_str());
        } else {
            std::fprintf(stderr, "No help available for '%s'\n", args[0].c_str());
        }
        return 2;
    }
    printHelpText(h);
    return 0;
}

} // namespace gmx
