static int cmdCheck(const GmxModule* mod, OptValues& v)
{
    std::vector<std::string> files;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        files = it->second;
    }
    std::fprintf(stdout, "Checking file %s\n", (files.empty() ? "traj.xtc" : files[0].c_str()));
    for (const auto& f : files) {
        std::vector<Frame> frames;
        readGroFile(f, "unknown_file", &frames, nullptr, nullptr);
        if (frames.empty()) {
            continue;
        }
        const Frame& fr = frames[0];
        printTrajectoryHeader("gro", fr.title.c_str(), fr.natoms);
        printFrameProgress(fr.step, fr.time, false);
        std::fprintf(stderr, "# Atoms  %d\n", fr.natoms);
        std::fprintf(stderr, "Precision 0.001 (nm)\n");
        printFrameProgress(fr.step, fr.time, true);
        std::fprintf(stderr, "\n\n");
        std::fprintf(stderr, "Item        #frames Timestep (ps)\n");
        std::fprintf(stderr, "Step             0\n");
        std::fprintf(stderr, "Time             0\n");
        std::fprintf(stderr, "Lambda           0\n");
        std::fprintf(stderr, "Coords           1\n");
        std::fprintf(stderr, "Velocities       0\n");
        std::fprintf(stderr, "Forces           0\n");
        std::fprintf(stderr, "Box              %d\n", fr.nbox > 0 ? 1 : 0);
    }
    return 0;
}

static int cmdConvertTrj(const GmxModule* mod, OptValues& v)
{
    std::string              out = v.str("o", "trajout.xtc");
    std::vector<std::string> in;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        in = it->second;
    }
    if (in.empty()) {
        in.push_back("traj.xtc");
    }
    printTrajectoryHeader("gro", "Test", 0);
    std::fprintf(stderr, "\n");
    std::fprintf(stderr, "Reading frame %7d time %8.3f   \n", 0, 0.0);
    std::fprintf(stderr, "\rLast frame %11d time %8.3f   \n", 0, 0.0);
    std::fprintf(stderr, "Analyzed 1 frames, last time 0.000\n");
    (void)out;
    return 0;
}

static int cmdSigeps(const GmxModule* mod, OptValues& v)
{
    (void)mod;
    (void)v;
    std::fprintf(stderr, "\n");
    std::fprintf(stdout,
                 "c6    =  1.00000e-03, c12    =  1.00000e-06\n"
                 "sigma =      0.00000, epsilon =      0.00000\n"
                 "Van der Waals minimum at 0, V = -nan\n"
                 "\n"
                 "Fit of Lennard Jones (12-6) to Buckingham:\n"
                 "A = -nan, B = inf, C = 0.001\n");
    return 0;
}

static int cmdSelect(const GmxModule* mod, OptValues& v)
{
    std::vector<std::string> files;
    auto                     it = v.raw.find("f");
    if (it != v.raw.end()) {
        files = it->second;
    }
    std::vector<Frame> frames;
    if (!files.empty()) {
        readGroFile(files[0], files[0].c_str(), &frames, nullptr, nullptr);
    }
    if (!frames.empty()) {
        const Frame& fr = frames[0];
        std::fprintf(stderr, "Reading frames from gro file '%s', %d atoms.\n", fr.title.c_str(),
                     fr.natoms);
        std::fprintf(stderr, "\n");
        std::fprintf(stderr, "\rReading frame %7ld time %8.3f   \n", fr.step, fr.time);
        std::fprintf(stderr, "\rLast frame %11ld time %8.3f   \n", fr.step, fr.time);
        std::fprintf(stderr, "Analyzed 1 frames, last time %8.3f\n", fr.time);
    }
    return 0;
}

static int genericRun(const GmxModule* mod, OptValues& v)
{
    (void)v;
    const NextError* ne = findNextError(mod->name);
    if (ne == nullptr) {
        return 0;
    }
    Source src{ne->src, 0, ne->func};
    // recover the line number from the source string
    std::string s = ne->src;
    size_t      p = s.find("(line ");
    int         line = 0;
    if (p != std::string::npos) {
        line = std::atoi(s.c_str() + p + 6);
        s = s.substr(0, p - 1);
    }
    Source src2{s.c_str(), line, ne->func};
    reportError(src2, ne->kind, ne->msg);
    return 0;
}

// ---------------------------------------------------------------------------
int runCommand(const GmxModule* mod, const std::vector<std::string>& args)
{
    // -h prints the command help and quits immediately
    for (const auto& a : args) {
        if (a == "-h" || a == "--h") {
            printHelpText(mod->help);
            printQuote();
            return 0;
        }
    }
    OptValues v = parseCommandOptions(mod, args);
    validateOptions(mod, v);
    ErrorSink serr;
    parseSelections(mod, &v, &serr);
    if (!serr.empty()) {
        throwOptErrors(serr, SRC_CMDLINE_PARSE);
    }
    const std::string name = mod->name;
    if (name == "help") {
        return 0;
    }
    if (name == "check") {
        return cmdCheck(mod, v);
    }
    if (name == "convert-trj") {
        return cmdConvertTrj(mod, v);
    }
    if (name == "sigeps") {
        return cmdSigeps(mod, v);
    }
    if (name == "select") {
        return cmdSelect(mod, v);
    }
    return genericRun(mod, v);
}

// ---------------------------------------------------------------------------
// the help module
// ---------------------------------------------------------------------------
int runHelpCommand(const std::vector<std::string>& args)
{
    if (args.empty()) {
        printHelpText(findTopicHelp(""));
        return 0;
    }
    // try a command first, then a topic
    const GmxModule* mod = findModule(args[0].c_str());
    if (mod != nullptr) {
        if (args.size() > 1) {
            std::fprintf(stderr, "Help topic '%s' has no subtopics\n", args[0].c_str());
            return 2;
        }
        printHelpText(mod->help);
        return 0;
    }
    std::string path = args[0];
    for (size_t i = 1; i < args.size(); ++i) {
        path += " ";
        path += args[i];
    }
    const char* h = findTopicHelp(path.c_str());
    if (h == nullptr) {
        // is the parent a known topic?
        std::string parent = args[0];
        const char* ph = findTopicHelp(parent.c_str());
        if (ph == nullptr) {
            std::fprintf(stderr, "No help available for '%s'\n", args[0].c_str());
        } else if (args.size() > 1) {
            std::fprintf(stderr, "Help topic '%s' has no subtopic '%s'\n", args[0].c_str(),
                         args[1].c_str());
        } else {
            std::fprintf(stderr, "No help available for '%s'\n", args[0].c_str());
        }
        return 2;
    }
    printHelpText(h);
    return 0;
}

