"""Compare the reimplemented binary against data captured from the reference."""
import os, subprocess, sys, re, difflib, json
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
BIN = os.path.join(ROOT, 'executable')
WORK = '/tmp/dt'
def run(args, cwd=WORK, stdin=''):
    os.makedirs(cwd, exist_ok=True)
    p = subprocess.run([BIN] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                       input=stdin.encode(), cwd=cwd, timeout=20)
    return p.returncode, p.stdout.decode('utf8', 'replace'), p.stderr.decode('utf8', 'replace')

def check(name, args, exp_out, exp_err, exp_rc, cwd=WORK, stdin='', verbose=False):
    rc, so, se = run(args, cwd=cwd, stdin=stdin)
    ok = True
    msgs = []
    if exp_out is not None and so != exp_out:
        ok = False
        msgs.append('stdout differs:\n' + '\n'.join(list(difflib.unified_diff(exp_out.split('\n'), so.split('\n')))[:20]))
    if exp_err is not None and se != exp_err:
        ok = False
        msgs.append('stderr differs:\n' + '\n'.join(list(difflib.unified_diff(exp_err.split('\n'), se.split('\n')))[:20]))
    if exp_rc is not None and rc != exp_rc:
        ok = False
        msgs.append('rc %d != %d' % (rc, exp_rc))
    if verbose or not ok:
        print(('PASS ' if ok else 'FAIL ') + name)
        for m in msgs:
            print('   ' + m.replace('\n', '\n   '))
    return ok

if __name__ == '__main__':
    cases = json.load(open(os.path.join(ROOT, 'data', 'difftest.json'))) if os.path.exists(os.path.join(ROOT, 'data', 'difftest.json')) else []
    npass = nfail = 0
    for c in cases:
        if check(c['name'], c['args'], c.get('out'), c.get('err'), c.get('rc')):
            npass += 1
        else:
            nfail += 1
    print('%d passed, %d failed' % (npass, nfail))
PYEOF
echo ok"}

