    if v.get('blocks'):
        b=v['blocks'][-1]
        e={'src':b['src'],'func':b['func'],'kind':b['kind'],'msg':b['msg'],
           'stdout':v.get('so') or '','rc':v.get('rc')}
    elif cmd in ne and ne[cmd].get('src'):
        e={'src':ne[cmd]['src'],'func':ne[cmd]['func'],'kind':ne[cmd]['kind'],
           'msg':ne[cmd]['msg'],'stdout':'','rc':ne[cmd]['rc']}
    elif cmd in na2 and cmd not in noargs:
        e={'src':na2[cmd]['src'],'func':na2[cmd]['func'],'kind':na2[cmd]['kind'],
           'msg':na2[cmd]['msg'],'stdout':'','rc':1}
    if e:
        out[cmd]=e
json.dump(out, open('data/runtime.json','w'), indent=1)
print(len(out),'entries')
for k in ['energy','trjcat','trjconv','filter','angle','anaeig']:
    print(k, json.dumps(out.get(k))[:150])
PY"}

